/**
 * This file implements a catch-all route that renders the user-facing pages
 * generated by Puck. For any route visited (with exception of other hardcoded
 * pages in /app), it will check your database (via `getPage`) for a Puck page
 * and render it using <Render>.
 */

import { notFound } from "next/navigation";
import { Metadata } from "next";
import { getPage } from "pageEditor/lib/get-page";
import { Client } from "./client";

// Helper function to validate slug pattern
function isValidSlugArray(slug: string[]): boolean {
    // Check if slug array is empty or undefined
    if (!slug || !Array.isArray(slug) || slug.length === 0) {
        return false;
    }
    
    // Check if any slug segment contains dots (like com.chrome.devtools or file.json)
    return !slug.some(segment => segment.includes('.'));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string[] }>;
}): Promise<Metadata> {
  const { slug = [] } = await params;
  
  if (!isValidSlugArray(slug)) {
    return {
      title: "Page Not Found",
      description: "The requested page could not be found",
    };
  }
  
  const path = `/${slug.join("/")}`;
  const pageData = getPage(path);
  
  if (!pageData) {

    return {
      title: "Page Not Found",
      description: "The requested page could not be found",
    };
  }

  const { root } = pageData;
  const props = root?.props || {};

  // Construct the canonical URL
  const baseUrl = process.env.NEXT_PUBLIC_WEBSITE_URL || '';
  const canonicalUrl = `${baseUrl}${path}`;

  // Default image for social media
  const defaultImage = `${baseUrl}/images/og-image.jpg`;

  const metadata: Metadata = {
    title: props.title || process.env.NEXT_PUBLIC_APP_OG_TITLE || "",
    description: props.description || process.env.NEXT_PUBLIC_APP_OG_DESC || "",
    keywords: typeof props.keywords === 'string' ? props.keywords : props.keywords?.join(', '),
    publisher: process.env.NEXT_PUBLIC_PUBLISHER_NAME || "",
    
    // Canonical URL
    alternates: {
      canonical: canonicalUrl,
    },

    // Open Graph tags
    openGraph: {
      title: props.ogTitle || props.title || process.env.NEXT_PUBLIC_APP_OG_TITLE || "",
      description: props.ogDescription || props.description || process.env.NEXT_PUBLIC_APP_OG_DESC || "",
      url: canonicalUrl,
      siteName: process.env.NEXT_PUBLIC_APP_NAME || "",
      type: "website",
      locale: "en_US",
      images: [
        {
          url: props.ogImage || defaultImage,
          width: 1200,
          height: 630,
          alt: props.title || process.env.NEXT_PUBLIC_APP_NAME || "",
        },
      ],
    },

    // Twitter Card tags
    twitter: {
      card: "summary_large_image",
      title: props.twitterTitle || props.ogTitle || props.title || process.env.NEXT_PUBLIC_APP_OG_TITLE || "",
      description: props.twitterDescription || props.ogDescription || props.description || process.env.NEXT_PUBLIC_APP_OG_DESC || "",
      site: process.env.NEXT_PUBLIC_SOCIAL_TWITTER || "",
      creator: process.env.NEXT_PUBLIC_SOCIAL_TWITTER || "",
      images: [props.twitterImage || props.ogImage || defaultImage],
    },

    // Robots meta tags
    robots: {
      index: !props.noIndex,
      follow: !props.noFollow,
      noarchive: props.noArchive || false,
      nosnippet: props.noSnippet || false,
      noimageindex: props.noImageIndex || false,
      googleBot: {
        index: !props.noIndex,
        follow: !props.noFollow,
        noarchive: props.noArchive || false,
        nosnippet: props.noSnippet || false,
        noimageindex: props.noImageIndex || false,
      },
    },

    // Additional meta tags for better SEO
    other: {
      'og:image:alt': props.title || process.env.NEXT_PUBLIC_APP_NAME || "",
      'twitter:image:alt': props.title || process.env.NEXT_PUBLIC_APP_NAME || "",
      'author': process.env.NEXT_PUBLIC_APP_NAME || "",
      'viewport': 'width=device-width, initial-scale=1',
      'format-detection': 'telephone=no',
    },

    // Verification meta tags (if needed)
    verification: {
      google: process.env.GOOGLE_SITE_VERIFICATION,
      yandex: process.env.YANDEX_VERIFICATION,
      yahoo: process.env.YAHOO_VERIFICATION,
    },
  };

  return metadata;
}

export default async function CatchAllPage({
  params,
}: {
  params: Promise<{ slug: string[] }>;
}) {
  const { slug = [] } = await params;
  
  if (!isValidSlugArray(slug)) {
    return notFound();
  }
  
  const path = `/${slug.join("/")}`;
  const data = getPage(path);

  if (!data) {
    return notFound();
  }

  return <Client data={data} />;
} 